mapper.select:
select t1.* from ( select t.*, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = t.unit_id ) AS unit_id_n, ( SELECT s.DESCRIPTION FROM sys_user s WHERE s.USER_ID = t.CREATED_BY ) CREATED_BY_n, ( SELECT s.DESCRIPTION FROM sys_user s,sys_user_allocation a WHERE a.ALLOCATION_ID = t.NEXT_APPROVE_PERSON and s.user_id = a.user_id) NEXT_APPROVE_PERSON_N, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'GENERAL_STATUS' AND scb.CODE_ID = scv.CODE_ID and scv.value = t.status) status_n, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'SYS.YES_NO' AND scb.CODE_ID = scv.CODE_ID and scv.value = t.final_approve_flag) final_approve_flag_n from hls_general_issue t) t1
1=1
and t1.created_by_n = #{createdByN}
and t1.created_by = #{createdBy}
and t1.general_id=#{generalId}

select t1.* from ( select t.*, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = t.unit_id ) AS unit_id_n, ( SELECT s.DESCRIPTION FROM sys_user s WHERE s.USER_ID = t.CREATED_BY ) CREATED_BY_n, ( SELECT s.DESCRIPTION FROM sys_user s,sys_user_allocation a WHERE a.ALLOCATION_ID = t.NEXT_APPROVE_PERSON and s.user_id = a.user_id) NEXT_APPROVE_PERSON_N, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'GENERAL_STATUS' AND scb.CODE_ID = scv.CODE_ID and scv.value = t.status) status_n, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'SYS.YES_NO' AND scb.CODE_ID = scv.CODE_ID and scv.value = t.final_approve_flag) final_approve_flag_n, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'COMMON_ADJUST_TYPE' AND scb.CODE_ID = scv.CODE_ID and scv.value = t.common_adjust_type)common_adjust_type_n from hls_general_issue t) t1
1=1
and (t1.created_by = #{authority} or EXISTS (SELECT 1 FROM sys_user U LEFT JOIN SYS_USER_ALLOCATION UR ON UR.USER_ID = U.USER_ID LEFT JOIN SYS_ROLE_B R ON R.ROLE_ID = UR.ROLE_ID WHERE R.ROLE_CODE = 'ADMIN' and U.USER_ID = #{authority}))
and t1.apply_date >= to_date( #{applyDateFrom}, 'YYYY-MM-DD')
and t1.apply_date <= to_date( #{applyDateTo}, 'YYYY-MM-DD')
and t1.created_by_n = #{createdByN}
and t1.created_by = #{createdBy}
and t1.general_id=#{generalId}

select t1.* from ( select t.*, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = t.unit_id ) AS unit_id_n, ( SELECT s.DESCRIPTION FROM sys_user s WHERE s.USER_ID = t.CREATED_BY ) CREATED_BY_n, ( SELECT s.DESCRIPTION FROM sys_user s,sys_user_allocation a WHERE a.ALLOCATION_ID = t.NEXT_APPROVE_PERSON and s.user_id = a.user_id) NEXT_APPROVE_PERSON_N, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'GENERAL_STATUS' AND scb.CODE_ID = scv.CODE_ID and scv.value = t.status) status_n, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'SYS.YES_NO' AND scb.CODE_ID = scv.CODE_ID and scv.value = t.final_approve_flag) final_approve_flag_n, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'COMMON_ADJUST_TYPE' AND scb.CODE_ID = scv.CODE_ID and scv.value = t.common_adjust_type) common_adjust_type_n from hls_general_issue t) t1
1=1
and t1.apply_date >= to_date( #{applyDateFrom}, 'YYYY-MM-DD')
and t1.apply_date <= to_date( #{applyDateTo}, 'YYYY-MM-DD')
and t1.created_by_n = #{createdByN}
and t1.created_by = #{createdBy}
and t1.general_id=#{generalId}
